#!/usr/bin/env python3
"""Validator for the Halcyon Threshold Commitment Ledger.

The ledger's only asset is being right. This script enforces the mechanical half
of that: schema conformance, evidence requirements, and review staleness. It
cannot check whether a quote is accurate -- that is the checker's job (see
CONTRIBUTING.md).

Usage:
    python verify.py ledger/commitments.csv
    python verify.py ledger/commitments.csv --due
    python verify.py ledger/commitments.csv --due --as-of 2027-03-01

Exit codes:
    0  clean (warnings may still be present)
    1  one or more errors -- do not commit
    2  could not read or parse the file
"""

import argparse
import csv
import datetime as dt
import re
import sys

FIELDS = [
    "id", "developer", "commitment_text", "source_url", "source_archive_url",
    "source_type", "date_made", "scope", "deadline", "specificity",
    "verifiability", "status", "status_evidence_url", "status_archive_url",
    "last_reviewed", "review_interval_days", "reviewer", "right_of_reply",
    "notes",
]

ALWAYS_REQUIRED = [
    "id", "developer", "commitment_text", "source_url", "source_archive_url",
    "source_type", "date_made", "scope", "deadline", "specificity",
    "verifiability", "status", "last_reviewed", "review_interval_days",
    "reviewer",
]

SOURCE_TYPES = {
    "policy_doc", "blog_post", "testimony", "regulatory_filing",
    "press_statement", "technical_report",
}
VERIFIABILITY = {"publicly_checkable", "third_party_auditable", "self_reported_only"}
STATUSES = {
    "active", "kept", "partially_kept", "missed", "withdrawn", "superseded",
    "unclear",
}
SPECIFICITY = {"1", "2", "3"}

ID_RE = re.compile(r"^HT-\d{4}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
REPLY_RE = re.compile(r"^(sent|responded|declined):\d{4}-\d{2}-\d{2}$")

MAX_QUOTE = 300
EXAMPLE_ID = "HT-0000"

# Words that signal editorialising in a field that is supposed to be neutral.
LOADED = [
    "disappointingly", "predictably", "as expected", "yet again", "of course",
    "unsurprisingly", "egregious", "shameful", "blatant", "obviously",
]


def parse_date(value):
    if not DATE_RE.match(value or ""):
        return None
    try:
        return dt.date.fromisoformat(value)
    except ValueError:
        return None


def is_url(value):
    return isinstance(value, str) and value.startswith(("http://", "https://"))


class Report:
    def __init__(self):
        self.errors = []
        self.warnings = []

    def error(self, line, entry_id, message):
        self.errors.append((line, entry_id, message))

    def warn(self, line, entry_id, message):
        self.warnings.append((line, entry_id, message))


def check_row(row, line, report, seen_ids, today):
    entry_id = (row.get("id") or "").strip()

    if not ID_RE.match(entry_id):
        report.error(line, entry_id or "?", "id must look like HT-0001")
    if entry_id in seen_ids:
        report.error(line, entry_id, "duplicate id (ids are never reused)")
    seen_ids.add(entry_id)

    for field in ALWAYS_REQUIRED:
        if not (row.get(field) or "").strip():
            report.error(line, entry_id, "missing required field: %s" % field)

    # Enumerations.
    for field, allowed in (
        ("source_type", SOURCE_TYPES),
        ("verifiability", VERIFIABILITY),
        ("status", STATUSES),
        ("specificity", SPECIFICITY),
    ):
        value = (row.get(field) or "").strip()
        if value and value not in allowed:
            report.error(
                line, entry_id,
                "%s=%r is not one of: %s" % (field, value, ", ".join(sorted(allowed))),
            )

    # Quotes must be verbatim and short enough to be one commitment.
    quote = (row.get("commitment_text") or "").strip()
    if len(quote) > MAX_QUOTE:
        report.error(
            line, entry_id,
            "commitment_text is %d chars (max %d) -- this is probably two "
            "commitments, split it" % (len(quote), MAX_QUOTE),
        )

    # Primary sources, not coverage of them. Archive links are not optional.
    for field in ("source_url", "source_archive_url"):
        value = (row.get(field) or "").strip()
        if value and not is_url(value):
            report.error(line, entry_id, "%s is not a URL" % field)

    # Dates.
    date_made = parse_date((row.get("date_made") or "").strip())
    if (row.get("date_made") or "").strip() and not date_made:
        report.error(line, entry_id, "date_made must be YYYY-MM-DD")
    last_reviewed = parse_date((row.get("last_reviewed") or "").strip())
    if (row.get("last_reviewed") or "").strip() and not last_reviewed:
        report.error(line, entry_id, "last_reviewed must be YYYY-MM-DD")

    if date_made and date_made > today:
        report.error(line, entry_id, "date_made is in the future")
    if last_reviewed and date_made and last_reviewed < date_made:
        report.error(line, entry_id, "last_reviewed is before date_made")

    deadline_raw = (row.get("deadline") or "").strip()
    deadline = None
    if deadline_raw and deadline_raw not in ("ongoing", "none_stated"):
        deadline = parse_date(deadline_raw)
        if not deadline:
            report.error(
                line, entry_id,
                "deadline must be YYYY-MM-DD, 'ongoing', or 'none_stated'",
            )

    interval_raw = (row.get("review_interval_days") or "").strip()
    interval = None
    if interval_raw:
        if not interval_raw.isdigit() or int(interval_raw) <= 0:
            report.error(line, entry_id, "review_interval_days must be a positive integer")
        else:
            interval = int(interval_raw)

    status = (row.get("status") or "").strip()

    # A status change requires evidence. Never inference alone.
    if status and status != "active":
        for field in ("status_evidence_url", "status_archive_url"):
            value = (row.get(field) or "").strip()
            if not value:
                report.error(
                    line, entry_id,
                    "status=%s requires %s -- no evidence, no status change"
                    % (status, field),
                )
            elif not is_url(value):
                report.error(line, entry_id, "%s is not a URL" % field)

    # Right of reply is mandatory before publishing a 'missed'.
    reply = (row.get("right_of_reply") or "").strip()
    if status == "missed":
        if not reply:
            report.error(
                line, entry_id,
                "status=missed requires right_of_reply (see SCHEMA.md s4) before "
                "publication",
            )
        elif not REPLY_RE.match(reply):
            report.error(
                line, entry_id,
                "right_of_reply must be sent:/responded:/declined: plus YYYY-MM-DD",
            )
        elif reply.startswith("sent:"):
            sent = parse_date(reply.split(":", 1)[1])
            if sent and (today - sent).days < 14:
                report.warn(
                    line, entry_id,
                    "right of reply sent %d days ago; ten working days have not "
                    "elapsed -- hold publication" % (today - sent).days,
                )
    elif reply and not REPLY_RE.match(reply):
        report.error(line, entry_id, "right_of_reply is malformed")

    # Judgement nudges -- warnings, not errors.
    if status == "missed" and (row.get("verifiability") or "").strip() == "self_reported_only":
        report.warn(
            line, entry_id,
            "status=missed on a self-reported-only commitment: if nobody outside "
            "could check it, 'unclear' is usually the honest status",
        )

    if (row.get("specificity") or "").strip() == "1":
        report.warn(
            line, entry_id,
            "specificity=1 is directional only and usually fails the 'checkable' "
            "criterion -- reconsider whether this belongs in the ledger",
        )

    if deadline and status == "active" and deadline < today:
        report.warn(
            line, entry_id,
            "deadline passed on %s but status is still 'active' -- needs a review"
            % deadline.isoformat(),
        )

    if deadline and interval and deadline >= today and (deadline - today).days <= 90 \
            and interval > 30:
        report.warn(
            line, entry_id,
            "deadline is within 90 days; review_interval_days should be 30",
        )

    notes = (row.get("notes") or "").lower()
    for word in LOADED:
        if word in notes:
            report.warn(
                line, entry_id,
                "notes contain %r -- the ledger does not editorialise (SCHEMA.md s6)"
                % word,
            )

    return {
        "id": entry_id,
        "line": line,
        "last_reviewed": last_reviewed,
        "interval": interval,
        "status": status,
        "developer": (row.get("developer") or "").strip(),
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description="Validate the Commitment Ledger.")
    parser.add_argument("path", nargs="?", default="ledger/commitments.csv")
    parser.add_argument("--due", action="store_true",
                        help="list entries past their review date")
    parser.add_argument("--as-of", default=None,
                        help="evaluate dates as of YYYY-MM-DD (default: today)")
    parser.add_argument("--quiet", action="store_true",
                        help="suppress warnings")
    args = parser.parse_args(argv)

    if args.as_of:
        today = parse_date(args.as_of)
        if not today:
            print("--as-of must be YYYY-MM-DD", file=sys.stderr)
            return 2
    else:
        today = dt.date.today()

    try:
        with open(args.path, newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            header = reader.fieldnames or []
            if header != FIELDS:
                print("ERROR: header does not match the schema.", file=sys.stderr)
                missing = [f for f in FIELDS if f not in header]
                extra = [f for f in header if f not in FIELDS]
                if missing:
                    print("  missing columns: %s" % ", ".join(missing), file=sys.stderr)
                if extra:
                    print("  unexpected columns: %s" % ", ".join(extra), file=sys.stderr)
                if not missing and not extra:
                    print("  columns are out of order; expected:\n  %s"
                          % ",".join(FIELDS), file=sys.stderr)
                return 2
            rows = list(reader)
    except FileNotFoundError:
        print("ERROR: no such file: %s" % args.path, file=sys.stderr)
        return 2
    except (csv.Error, UnicodeDecodeError) as exc:
        print("ERROR: could not parse %s: %s" % (args.path, exc), file=sys.stderr)
        return 2

    report = Report()
    seen_ids = set()
    summaries = []
    for offset, row in enumerate(rows):
        summaries.append(check_row(row, offset + 2, report, seen_ids, today))

    real = [s for s in summaries if s["id"] != EXAMPLE_ID]

    for line, entry_id, message in report.errors:
        print("ERROR  line %d  %s: %s" % (line, entry_id, message))
    if not args.quiet:
        for line, entry_id, message in report.warnings:
            print("WARN   line %d  %s: %s" % (line, entry_id, message))

    print()
    print("%d row(s) checked (%d real entries, %d example)."
          % (len(summaries), len(real), len(summaries) - len(real)))
    print("%d error(s), %d warning(s)." % (len(report.errors), len(report.warnings)))

    if real:
        by_status = {}
        for summary in real:
            by_status[summary["status"]] = by_status.get(summary["status"], 0) + 1
        print("status: " + ", ".join(
            "%s=%d" % (k, v) for k, v in sorted(by_status.items())))
        developers = sorted({s["developer"] for s in real if s["developer"]})
        print("developers covered: %d" % len(developers))

    if args.due:
        due = []
        for summary in real:
            if summary["last_reviewed"] and summary["interval"]:
                next_review = summary["last_reviewed"] + dt.timedelta(
                    days=summary["interval"])
                if next_review <= today:
                    due.append((next_review, summary))
        print()
        if due:
            print("Due for review (%d):" % len(due))
            for next_review, summary in sorted(due, key=lambda item: item[0]):
                print("  %s  %s  (due %s, %d days overdue)" % (
                    summary["id"], summary["developer"], next_review.isoformat(),
                    (today - next_review).days))
        else:
            print("Nothing due for review.")

    if not real:
        print()
        print("Note: no real entries yet. The ledger is machinery waiting for "
              "evidence -- see ledger/CONTRIBUTING.md.")

    return 1 if report.errors else 0


if __name__ == "__main__":
    sys.exit(main())
